function plLang() {
  var l = (document.documentElement.getAttribute('lang') || 'fa').toLowerCase();
  return l.indexOf('fa') === 0 ? 'fa' : 'en';
}

function plNum(n) {
  var s = String(n);
  if (plLang() !== 'fa') return s;
  return s.replace(/[0-9]/g, function (d) { return '۰۱۲۳۴۵۶۷۸۹'[d]; });
}

function pst(key, vars) {
  var cat = PL_MESSAGES[plLang()] || PL_MESSAGES.en;
  var s = cat[key] !== undefined ? cat[key] : (PL_MESSAGES.en[key] !== undefined ? PL_MESSAGES.en[key] : key);
  if (vars) s = s.replace(/\{(\w+)\}/g, function (m, k) { return vars[k] === undefined ? m : typeof vars[k] === 'number' ? plNum(vars[k]) : vars[k]; });
  return s;
}

var PL_KEY = 'nakama.plane';
var PL_RAIL_KEY = 'nakama.plane.rail';
var root = document.documentElement;

function plEnabled() {
  var m = /[?&]plane=([01])\b/.exec(location.search) || /[?&]plane=([01])\b/.exec(location.hash);
  try {
    if (m && m[1] === '0') localStorage.setItem(PL_KEY, '0');
    else if (m && m[1] === '1') localStorage.removeItem(PL_KEY);
    return localStorage.getItem(PL_KEY) !== '0';
  } catch (e) {
    return !(m && m[1] === '0');
  }
}

if (!plEnabled()) return;
root.classList.add('pl');

var mqReduce = window.matchMedia ? window.matchMedia('(prefers-reduced-motion: reduce)') : { matches: false };
var mqMobile = window.matchMedia ? window.matchMedia('(max-width: 767px)') : { matches: false };

function reduced() {
  return !!mqReduce.matches;
}

function isRtl() {
  return (root.getAttribute('dir') || 'ltr') === 'rtl';
}

function nc() {
  return window.NakamaConsole || null;
}

function el(tag, props) {
  var e = document.createElement(tag);
  if (props) {
    for (var k in props) {
      var v = props[k];
      if (v === null || v === undefined || v === false) continue;
      if (k === 'text') e.textContent = v;
      else if (k === 'html') e.innerHTML = v;
      else if (k.indexOf('on') === 0 && typeof v === 'function') e.addEventListener(k.slice(2), v);
      else e.setAttribute(k, v === true ? '' : v);
    }
  }
  for (var i = 2; i < arguments.length; i++) {
    var c = arguments[i];
    if (c === null || c === undefined || c === false) continue;
    e.appendChild(typeof c === 'string' ? document.createTextNode(c) : c);
  }
  return e;
}

